def brief_bytes(run, manifest, analysis):
    lines = ["# Regulatory change impact brief", "", f"Run: `{run['run_id']}` · Review date: **{REVIEW_DATE}** · Status: **{analysis['status']}**",
             "", "**Draft for Legal and Operations. All legal interpretations, exceptions, activation, approved dates and incident closure remain pending human decisions. Review requests are prepared and unsent.**",
             "", "This brief summarizes the full reasoning in `impact-register.csv` and snapshots 03–06. `sources/manifest.json` preserves every attempt, exact retrieval time, source version and evidence hash; retrieval times do not change the review date. Detached final-draft and source-version bindings are in `deliverables/review-request-bindings.json`.", "", "## Source access and version limits", "",
             "| Route / attempts | Source identity and version | Latest retrieval | Suitability / historical limit |", "|---|---|---|---|"]
    for label in LABELS:
        attempts = [s for s in manifest["sources"] if s["label"] == label]
        successful = [s for s in attempts if s['retrieval_status'] == 'retrieved']
        source = max(successful or attempts, key=lambda s: s['retrieved_at'])
        version = source.get("version_metadata") or {}
        version_labels = [str(version[k]) for k in ("version", "version_date", "policy_version", "context_revision", "context_observation_date", "context_authored_date", "last_update", "publication_date", "effective_date") if version.get(k)]
        row_versions = {r.get("record_version") or r.get("source_version") for r in source.get("normalized_records", [])} - {None, ""}
        version_labels.extend(sorted(row_versions))
        identity = str(version.get("identity") or version.get("title") or "Identity not established")
        identity_version = identity + ("; " + "; ".join(version_labels) if version_labels else "; version not established")
        limits = [str(version[k]) for k in ("authority_limit", "historical_limit", "review_suitability") if version.get(k)]
        if not limits:
            limits = ["Suitable captured version" if version.get("suitable_for_review") is True else "Historical suitability not established"]
        failures = [s for s in attempts if s.get("error")]
        limits.extend(f"{s['id']}: {s['error']}" for s in failures)
        values = (f"[{label}]({source['locator']}): " + "; ".join(f"{s['id']} {s['retrieval_status']}" for s in attempts), identity_version, max(s["retrieved_at"] for s in attempts), " ".join(limits))
        lines.append("| " + " | ".join(md_escape(value) for value in values) + " |")
    lines += ["", "## Authority and timing basis", ""]
    for key in ("binding_rules", "timing_rules", "guidance_context"):
        for item in analysis.get(key, []):
            lines.append(f"- `{item['id']}` {item['summary']} Basis: {', '.join('`'+e+'`' for e in item['evidence_ids'])}.")
    lines += ["", "Exact quotations, locators and company facts remain in `snapshots/03-authority-and-timing.json` and `snapshots/04-evidence-reconciliation.json`; evidence states do not establish compliance."]
    impacts = analysis.get("impacts", [])
    counts = {state: sum(i["state"] == state for i in impacts) for state in ("supported-impact", "supported-no-impact", "conflicting", "unresolved")}
    lines += ["", "## Findings", "", "; ".join(f"{count} {state}" for state, count in counts.items()) + ". Full rule, evidence and proposal reasoning is in `impact-register.csv`.", "",
              "| Impact / system / rule | State | Finding | Owner / linked proposals |", "|---|---|---|---|"]
    for impact in [i for i in impacts if i["state"] != "supported-no-impact"]:
        action_ids = impact.get("action_ids", []) or [a.get("action_id", a["id"]) for a in analysis.get("proposed_actions", []) if impact["id"] in a.get("impact_ids", [])]
        values = (f"{impact['id']} / {impact['system_id']} / {impact['rule_ref']}", impact["state"], impact["summary"], (impact.get("owner") or "pending assignment") + " / " + (", ".join(action_ids) or "none proposed"))
        lines.append("| " + " | ".join(md_escape(v) for v in values) + " |")
    no_impact = {}
    for impact in [i for i in impacts if i["state"] == "supported-no-impact"]:
        no_impact.setdefault(impact["system_id"], []).append(impact)
    if no_impact:
        lines += ["", "Bounded **supported-no-impact** proposals (specific rules and observed uses; no blanket compliance conclusion):"]
        for system, findings in sorted(no_impact.items()):
            lines.append(f"- `{system}`: " + "; ".join(f"`{i['id']}` / `{i['rule_ref']}`" for i in findings) + ". See the cited CSV rows for the complete limitations and source basis.")
    for item in analysis.get("unaffected_items", []):
        lines.append(f"- `{item['id']}` {item['summary']} (basis: {', '.join(item['evidence_ids'])}).")
    lines += ["", "## Conflicts and unresolved matters", ""]
    seen = set()
    for key in ("authority_blockers", "conflicts", "evidence_gaps", "unresolved_items", "escalations"):
        for item in analysis.get(key, []):
            if item["id"] in seen:
                continue
            seen.add(item["id"])
            lines.append(f"- `{item['id']}` {item['summary']} Owner: {item.get('owner') or 'pending assignment'}. Resolution: {item.get('resolution_need', item.get('question', 'see linked request'))}. Basis: {', '.join(item['evidence_ids'])}.")
    lines += ["", "## Proposed actions and calendar", ""]
    for action in analysis.get("proposed_actions", []):
        aid = action.get("action_id", action["id"])
        due = action.get("due_date") or "undated, omitted from calendar pending Operations"
        omitted = "; omitted from calendar: " + action.get("calendar_omission_reason", "unsupported date or blocked dependency") if action.get("calendar_eligible", True) is False else ""
        lines.append(f"- `{aid}` / `{action['system_id']}`: {action.get('action', action['summary'])}. {action.get('owner') or 'pending Operations'}; proposed **{due}**{omitted}; source status {action.get('status', 'draft')}; review {action.get('approval_required') or 'pending'}; approval **pending**. Basis: {', '.join(action['evidence_ids'])}.")
    lines += ["", "## Legal and Operations review requests", ""]
    lines += ["Each request below is **pending and unsent**, bound to this run and to the exact source versions and final draft hashes in `review-request-bindings.json` (matching `request_id`); full request evidence is in snapshot 06.", ""]
    for request in analysis.get("approval_requirements", []):
        subject = "; ".join(str(request[k]) for k in ("subject", "subject_system", "subject_impact", "subject_action") if request.get(k))
        lines.append(f"- `{request['request_id']}` ({request['id']}), **{request['required_reviewer']}**, {subject}: {request['question']}")
    lines += ["", "## Limitations", ""]
    lines.extend("- " + limitation for limitation in analysis.get("limitations", []))
    lines += ["", "## Recorded workflow decisions", ""]
    for decision in analysis.get("decisions", []):
        lines.append(f"- `{decision['id']}` {decision['summary']} Rationale: {decision['rationale']} Tradeoffs: {'; '.join(decision['tradeoffs'])}. Evidence: {', '.join(decision['evidence_ids'])}.")
    return ("\n".join(lines) + "\n").encode("utf-8")


